function reviewList(){root.innerHTML=formHeading('Review student submissions','Only submissions from your assigned courses are shown.')+(submissions.length?submissions.map(s=>'<article class="panel"><span class="eyebrow">'+esc(label(s.course_id))+'</span><h3>'+esc(s.title)+'</h3><p>'+esc(s.student_name)+' · '+esc(s.student_email)+'</p><p class="small muted">'+time(s.updated_at)+' · '+(s.graded_at?'Graded: '+esc(s.score)+'/100':'Awaiting review')+'</p><button class="btn secondary grade-open" data-id="'+s.id+'" type="button">Open submission</button></article>').join(''):'<div class="empty">No submissions to review yet.</div>');backBinding();document.querySelectorAll('.grade-open').forEach(b=>b.onclick=()=>gradeForm(b.dataset.id));}
async function gradeForm(id){root.innerHTML=formHeading('Opening student work','Retrieving the submission for review.')+loadingScreen('Opening submission…','Loading the answer and attachment details.');backBinding();try{const s=(await api('/submissions/'+id)).submission;root.innerHTML=formHeading('Review and grade',s.title)+'<section class="panel"><h2>Student answer</h2><p style="white-space:pre-wrap">'+esc(s.body||'No written answer; see attachment.')+'</p>'+(s.file_name?'<button class="btn secondary" id="review-file" type="button">Download '+esc(s.file_name)+'</button>':'')+'<form id="grade-form"><div class="field"><label for="score">Score out of 100</label><input id="score" name="score" type="number" min="0" max="100" step="0.01" value="'+esc(s.score??'')+'" required></div><div class="field"><label for="grade-feedback">Written feedback</label><textarea id="grade-feedback" name="feedback" maxlength="12000">'+esc(s.feedback||'')+'</textarea></div><button class="btn" type="submit">Publish score and feedback</button></form><div id="account-status" role="status" aria-live="polite"></div></section>';backBinding();if(s.file_name)document.getElementById('review-file').onclick=()=>downloadFile(s.id,s.file_name);document.getElementById('grade-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const fd=new FormData(e.target);await api('/submissions/'+id+'/grade','POST',{score:Number(fd.get('score')),feedback:fd.get('feedback')});await load();feedback('Score and feedback published to the student.');}catch(error){feedback(error.message,true);b.disabled=false;}};}catch(error){loadingFailure(error);}}
async function manageStaff(){root.innerHTML=formHeading('Lecturer access','Retrieving verified accounts and course details.')+loadingScreen('Loading lecturer access…','Preparing account and course details.');backBinding();try{const r=await api('/staff');root.innerHTML=formHeading('Assign lecturer access','Approve only verified lecturers and only for the courses they teach.')+'<form class="panel" id="staff-form"><div class="field"><label for="staff-user">Verified account</label><select id="staff-user" name="userId">'+r.members.map(m=>'<option value="'+m.user_id+'">'+esc(m.name)+' · '+esc(m.email)+' · '+esc(m.role)+'</option>').join('')+'</select></div><div class="field"><label for="staff-course">Course</label><select id="staff-course" name="courseId">'+options()+'</select></div><button class="btn" type="submit">Grant lecturer access to this course</button><div id="account-status" role="status" aria-live="polite"></div></form>';backBinding();document.getElementById('staff-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const fd=new FormData(e.target);await api('/staff/assign-course','POST',{userId:fd.get('userId'),courseId:fd.get('courseId')});feedback('Lecturer access assigned.');}catch(error){feedback(error.message,true);}finally{b.disabled=false;}};}catch(error){loadingFailure(error);}}
function adminSummary(){
 const data=adminOverview||{};return '<section aria-label="Cohort overview"><div class="stats admin-stats">'+[['Registered students',data.students],['Lecturers',data.lecturers],['Pending enrolments',data.pending_enrollments],['Approved enrolments',data.approved_enrollments],['Work awaiting grading',data.ungraded],['Upcoming classes',data.upcoming_classes]].map(([title,value])=>'<div class="stat"><strong>'+esc(value??0)+'</strong><span>'+title+'</span></div>').join('')+'</div><p class="small muted">'+esc(data.users??0)+' total accounts · '+esc(data.unverified??0)+' emails awaiting verification · '+esc(data.suspended??0)+' suspended accounts</p><div class="btn-row" style="margin-bottom:24px"><button class="btn" id="admin-users" type="button">Manage users</button><button class="btn secondary" id="admin-enrollments" type="button">Manage enrolments</button></div></section>';
}
function adminPagination(offset,total,handler){
 const prev=document.getElementById('admin-prev'),next=document.getElementById('admin-next');if(prev)prev.onclick=()=>handler(Math.max(0,offset-50));if(next)next.onclick=()=>handler(offset+50);
}
function paginationHTML(offset,total){return '<div class="btn-row"><button class="btn secondary" id="admin-prev" type="button" '+(offset===0?'disabled':'')+'>Previous</button><span class="small">'+(total?offset+1:0)+'–'+Math.min(offset+50,total)+' of '+total+'</span><button class="btn secondary" id="admin-next" type="button" '+(offset+50>=total?'disabled':'')+'>Next</button></div>';}
async function manageUsers(search='',offset=0){
 root.innerHTML=formHeading('User management','Search registered accounts, approve teaching access, and manage account availability.')+loadingScreen('Loading accounts…','Retrieving registered users.');backBinding();
 try{const r=await api('/admin/users?search='+encodeURIComponent(search)+'&offset='+offset);
 root.innerHTML=formHeading('User management','Administrator accounts are protected. Suspending an account blocks its learning API access; restoring it preserves all coursework.')+'<form id="admin-user-search" class="search-row"><label class="sr-only" for="admin-search">Search name or email</label><input id="admin-search" name="search" placeholder="Search name or email" value="'+esc(search)+'"><button class="btn" type="submit">Search users</button></form><div id="account-status" role="status" aria-live="polite"></div>'+r.users.map(u=>'<article class="panel"><div class="section-heading" style="margin-top:0"><h2>'+esc(u.name||'Unnamed account')+'</h2><span class="pill">'+esc(u.role)+'</span></div><p class="small">'+esc(u.email)+'</p><p class="small muted">'+(u.verified?'Email verified':'Email not verified')+' · '+(u.banned?'Identity provider blocked':u.suspended?'Learning access suspended':'Active account')+'</p><p class="small">Teaching: '+esc(u.teaching.map(label).join('; ')||'No courses assigned')+'</p><div class="btn-row">'+(u.role!=='admin'?'<button class="btn secondary user-status" data-id="'+u.user_id+'" type="button">'+(u.suspended?'Restore account':'Suspend account')+'</button>':'')+(u.role==='student'&&u.verified&&!u.suspended&&!u.banned?'<button class="btn secondary student-enroll" data-id="'+u.user_id+'" type="button">Assign course / cohort</button>':'')+'</div>'+(u.verified&&!u.suspended&&!u.banned?'<form class="user-teaching field" data-id="'+u.user_id+'"><label for="teach-'+u.user_id+'">Approve lecturer for a course</label><select id="teach-'+u.user_id+'" name="courseId">'+options()+'</select> <button class="btn secondary" type="submit">Approve course access</button></form>':'<p class="small muted">Teaching approval requires an active, verified account.</p>')+(u.teaching.length?'<div class="btn-row">'+u.teaching.map(id=>'<button class="btn secondary revoke-teaching" data-user="'+u.user_id+'" data-course="'+id+'" type="button">Revoke '+esc(label(id))+'</button>').join('')+'</div>':'')+'</article>').join('')+(r.users.length?'':'<div class="empty">No accounts match this search.</div>')+paginationHTML(offset,r.total);backBinding();adminPagination(offset,r.total,n=>manageUsers(search,n));
 document.getElementById('admin-user-search').onsubmit=e=>{e.preventDefault();manageUsers(new FormData(e.target).get('search'));};
 document.querySelectorAll('.user-status').forEach(b=>b.onclick=async()=>{const u=r.users.find(u=>u.user_id===b.dataset.id);if(!confirm((u.suspended?'Restore':'Suspend')+' learning access for '+u.email+'?'))return;try{await api('/admin/users/'+u.user_id+'/status','PUT',{suspended:!u.suspended});await manageUsers(search,offset);feedback('Account access updated.');}catch(error){feedback(error.message,true);}});
 document.querySelectorAll('.student-enroll').forEach(b=>b.onclick=()=>enrollmentForm(r.users.find(u=>u.user_id===b.dataset.id)));
 document.querySelectorAll('.user-teaching').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await api('/staff/assign-course','POST',{userId:form.dataset.id,courseId:new FormData(form).get('courseId')});await manageUsers(search,offset);feedback('Lecturer course access approved.');}catch(error){feedback(error.message,true);}});
 document.querySelectorAll('.revoke-teaching').forEach(b=>b.onclick=async()=>{if(!confirm('Revoke teaching access to '+label(b.dataset.course)+'? Existing work and grades will be kept.'))return;try{await api('/admin/teaching','PUT',{userId:b.dataset.user,courseId:b.dataset.course,active:false});await manageUsers(search,offset);feedback('Teaching access revoked.');}catch(error){feedback(error.message,true);}});
 }catch(error){loadingFailure(error);}
}
async function manageEnrollments(status='pending',search='',offset=0){
 root.innerHTML=formHeading('Enrolment management','Approve course requests and assign student cohorts.')+loadingScreen('Loading enrolments…','Retrieving course requests.');backBinding();
 try{const r=await api('/admin/enrollments?status='+encodeURIComponent(status)+'&search='+encodeURIComponent(search)+'&offset='+offset);
 root.innerHTML=formHeading('Enrolment management','Only approved enrolments provide access to lecturer assignments and class meeting details. To enrol a student directly, choose Assign course / cohort in User management.')+'<form class="search-row" id="enrolment-search"><label class="sr-only" for="enrol-status">Status</label><select id="enrol-status" name="status">'+['pending','approved','declined','all'].map(v=>'<option '+(status===v?'selected':'')+' value="'+v+'">'+v+'</option>').join('')+'</select><label class="sr-only" for="enrol-search">Search student or cohort</label><input id="enrol-search" name="search" placeholder="Search student or cohort" value="'+esc(search)+'"><button class="btn" type="submit">Filter enrolments</button></form><div id="account-status" role="status" aria-live="polite"></div>'+r.enrollments.map((e,i)=>'<article class="panel"><span class="pill">'+esc(e.status)+'</span><h2 style="margin-top:16px">'+esc(e.name)+'</h2><p class="small">'+esc(e.email)+'<br>'+esc(label(e.course_id))+'<br>'+esc(e.cohort)+'</p><button class="btn secondary edit-enrolment" data-index="'+i+'" type="button">Review / update enrolment</button></article>').join('')+(r.enrollments.length?'':'<div class="empty">No enrolments match these filters.</div>')+paginationHTML(offset,r.total);backBinding();adminPagination(offset,r.total,n=>manageEnrollments(status,search,n));
 document.getElementById('enrolment-search').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);manageEnrollments(fd.get('status'),fd.get('search'));};document.querySelectorAll('.edit-enrolment').forEach(b=>b.onclick=()=>{const e=r.enrollments[Number(b.dataset.index)];enrollmentForm(e,e);});
 }catch(error){loadingFailure(error);}
}
