 document.getElementById('admin-enrolment-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const fd=new FormData(e.target);await api('/admin/enrollments','PUT',{userId:user.user_id,courseId:enrollment?.course_id||fd.get('courseId'),cohort:fd.get('cohort'),status:fd.get('status')});await manageEnrollments();feedback('Enrolment saved.');}catch(error){feedback(error.message,true);}finally{button.disabled=false;}};
