function teachingSummary(){
 const rows=teachingOverview||[],sum=key=>rows.reduce((n,r)=>n+Number(r[key]||0),0);
 return '<section aria-label="Teaching overview"><div class="stats admin-stats">'+[['Assigned courses',rows.length],['Approved course enrolments',sum('students')],['Work awaiting grading',sum('ungraded')],['Upcoming classes',sum('upcoming_classes')],['Published lessons',sum('published_lessons')],['Draft lessons',sum('draft_lessons')]].map(([title,n])=>'<div class="stat"><strong>'+n+'</strong><span>'+title+'</span></div>').join('')+'</div></section>';
}
