 root.innerHTML=formHeading(staff?'Lessons and materials':'Lecturer lessons',courseId?label(courseId):'Select an approved course.')+loadingScreen('Loading lessons…','Retrieving course materials.');backBinding();
 if(!courseId){root.innerHTML=formHeading('Lessons and materials','Your course access is not ready yet.')+'<div class="empty">'+(staff?'Ask TIME to assign your teaching courses.':'Request enrolment and wait for administrator approval.')+'</div>';backBinding();return;}
 try{const r=await api('/lessons?courseId='+encodeURIComponent(courseId));
 root.innerHTML=formHeading(staff?'Lessons and materials':'Lecturer lessons',staff?'Draft privately, then publish when the lesson is ready for approved students.':'Published lessons and resources from your course staff.')+'<form class="search-row" id="lesson-course-filter"><label class="sr-only" for="lesson-course">Course</label><select id="lesson-course" name="courseId">'+options(accessibleCourses())+'</select><button class="btn secondary" type="submit">View course</button></form>'+(staff?'<button class="btn" id="create-lesson" type="button" style="margin-bottom:20px">Create lesson</button>':'')+r.lessons.map(l=>'<article class="panel"><span class="pill">'+(l.published?'Published':'Draft · staff only')+'</span><h2 style="margin-top:16px">'+esc(l.title)+'</h2><p class="small muted">Updated '+time(l.updated_at)+(l.file_name?'<br>Attachment: '+esc(l.file_name):'')+'</p><div class="btn-row"><button class="btn secondary open-lesson" data-id="'+l.id+'" type="button">Open lesson</button>'+(staff?'<button class="btn secondary edit-lesson" data-id="'+l.id+'" type="button">Edit lesson</button>':'')+'</div></article>').join('')+(r.lessons.length?'':'<div class="empty">'+(staff?'No lessons yet. Create your first draft.':'Your lecturer has not published lessons for this course yet.')+'</div>');backBinding();document.getElementById('lesson-course').value=courseId;document.getElementById('lesson-course-filter').onsubmit=e=>{e.preventDefault();courseLessons(new FormData(e.target).get('courseId'));};
 if(staff)document.getElementById('create-lesson').onclick=()=>lessonEditor(courseId);document.querySelectorAll('.open-lesson').forEach(b=>b.onclick=()=>openLesson(b.dataset.id));document.querySelectorAll('.edit-lesson').forEach(b=>b.onclick=()=>openLesson(b.dataset.id,true));
 }catch(error){loadingFailure(error);}
