let nextResourceRow=0;
function resourceRow(r={}){
 const n=nextResourceRow++;return '<fieldset class="resource-row" data-index="'+n+'"><legend>Resource link</legend><div class="field"><label for="resource-type-'+n+'">Type</label><select id="resource-type-'+n+'">'+['reading','pdf','slides','video'].map(t=>'<option value="'+t+'" '+(r.type===t?'selected':'')+'>'+t+'</option>').join('')+'</select></div><div class="field"><label for="resource-title-'+n+'">Resource title</label><input id="resource-title-'+n+'" maxlength="120" value="'+esc(r.title||'')+'" placeholder="For example: Week 1 presentation"></div><div class="field"><label for="resource-url-'+n+'">HTTPS link</label><input id="resource-url-'+n+'" type="url" maxlength="1500" value="'+esc(r.url||'')+'" placeholder="https://…"></div><button class="btn secondary remove-resource" type="button">Remove link</button></fieldset>';
}
function bindRemoveResources(){document.querySelectorAll('.remove-resource').forEach(b=>b.onclick=()=>b.closest('.resource-row').remove());}
function lessonEditor(courseId,lesson){
 nextResourceRow=0;root.innerHTML=formHeading(lesson?'Edit lesson':'Create lesson',label(courseId))+'<form class="panel" id="lesson-editor"><div class="field"><label for="lesson-title">Lesson title</label><input id="lesson-title" name="title" maxlength="160" required value="'+esc(lesson?.title||'')+'"></div><div class="field"><label for="lesson-content">Lesson content</label><textarea id="lesson-content" name="content" maxlength="40000" style="min-height:340px" required>'+esc(lesson?.content||'')+'</textarea></div><h2>Teaching resources</h2><p class="small muted">Add up to 10 HTTPS links to readings, PDFs, slide presentations, or videos.</p><div id="resource-rows">'+(lesson?.resources||[]).map(resourceRow).join('')+'</div><button class="btn secondary" id="add-resource" type="button">Add resource link</button><div class="field"><label for="lesson-attachment">PDF or text attachment (maximum 2 MB)</label><input id="lesson-attachment" type="file" accept=".pdf,.txt,application/pdf,text/plain"></div>'+(lesson?.file_name?'<p class="small">Current attachment: '+esc(lesson.file_name)+'. It is kept unless you replace or remove it.</p><label><input type="checkbox" name="removeFile"> Remove current attachment</label>':'')+'<label style="margin:24px 0"><input type="checkbox" name="published" '+(lesson?.published?'checked':'')+'> Publish for approved students in this course</label><p class="small muted">Leave publication unchecked to save a private staff draft. Upload only teaching materials you have permission to share, without private student or patient records.</p><button class="btn" type="submit">Save lesson</button><div id="account-status" role="status" aria-live="polite"></div></form>';backBinding();bindRemoveResources();
 document.getElementById('add-resource').onclick=()=>{if(document.querySelectorAll('.resource-row').length>=10){feedback('You can add up to 10 resource links.',true);return;}document.getElementById('resource-rows').insertAdjacentHTML('beforeend',resourceRow());bindRemoveResources();};
 document.getElementById('lesson-editor').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;feedback('Saving lesson…');try{const fd=new FormData(e.target),resources=[...document.querySelectorAll('.resource-row')].map(row=>{const n=row.dataset.index;return {type:document.getElementById('resource-type-'+n).value,title:document.getElementById('resource-title-'+n).value,url:document.getElementById('resource-url-'+n).value};}).filter(r=>r.title||r.url),data={courseId,title:fd.get('title'),content:fd.get('content'),resources,published:fd.has('published'),removeFile:fd.has('removeFile')};
 const f=document.getElementById('lesson-attachment').files[0];if(f){if(f.size>2097152)throw Error('Choose a file no larger than 2 MB.');const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));Object.assign(data,{fileName:f.name,fileType:f.type||(f.name.toLowerCase().endsWith('.txt')?'text/plain':'application/pdf'),fileData:btoa(binary)});}
 await api(lesson?'/lessons/'+lesson.id:'/lessons',lesson?'PUT':'POST',data);await courseLessons(courseId);feedback(data.published?'Lesson published for approved students.':'Lesson draft saved.');}catch(error){feedback(error.message,true);}finally{button.disabled=false;}};
}

function studentSummary(){
 const stats=studentOverview(profile,assignments,sessions),events=calendarEvents(assignments,sessions),next=events.filter(e=>e.at>=Date.now()&&(e.type==='class'||e.status==='To submit')).slice(0,4),grades=assignments.filter(a=>a.graded_at).sort((a,b)=>Date.parse(b.graded_at)-Date.parse(a.graded_at)).slice(0,3);
 return '<section aria-label="Your learning overview"><div class="stats student-stats">'+[['Approved courses',stats.approved],['Assignments to submit',stats.toSubmit],['Upcoming classes',stats.upcomingClasses],['Graded assignments',stats.graded]].map(([name,n])=>'<div class="stat"><strong>'+n+'</strong><span>'+name+'</span></div>').join('')+'</div><p class="small muted">'+stats.pendingEnrollments+' enrolment requests awaiting approval'+(stats.overdue?' · '+stats.overdue+' assignments overdue':'')+'</p><div class="btn-row" style="margin-bottom:24px"><button class="btn" id="student-calendar" type="button">My calendar</button><button class="btn secondary" id="student-announcements" type="button">Course announcements</button><button class="btn secondary" id="student-attendance" type="button">My attendance</button></div><div class="help-grid"><section class="panel"><h2>Coming up next</h2>'+(next.length?next.map(e=>'<div class="dashboard-update"><span class="pill">'+esc(e.status)+'</span><h3>'+esc(e.title)+'</h3><p class="small muted">'+esc(label(e.courseId))+'<br>'+time(e.at)+'</p></div>').join(''):'<p class="small muted">No upcoming deadlines or classes. Approved course updates will appear here.</p>')+'</section><section class="panel"><h2>Latest course announcements</h2>'+(announcements.length?announcements.slice(0,3).map(a=>'<div class="dashboard-update"><span class="small muted">'+esc(label(a.course_id))+'</span><h3>'+esc(a.title)+'</h3><p class="small">'+esc(a.content.slice(0,180))+(a.content.length>180?'…':'')+'</p></div>').join(''):'<p class="small muted">Your lecturers have not published announcements for your approved courses yet.</p>')+'</section></div>'+(grades.length?'<section class="panel" style="margin-top:20px"><h2>Recent grades and feedback</h2>'+grades.map(a=>'<div class="dashboard-update"><span class="pill">'+esc(a.score)+' / 100</span><h3>'+esc(a.title)+'</h3><p class="small muted">'+esc(label(a.course_id))+'</p><p class="small">'+esc(a.feedback||'No written feedback yet.')+'</p></div>').join('')+'</section>':'')+'</section>';
}
function calendarCard(e){return '<article class="panel"><span class="pill">'+esc(e.status)+'</span><h3 style="margin-top:14px">'+esc(e.title)+'</h3><p class="small muted">'+esc(label(e.courseId))+'<br>'+time(e.at)+'</p>'+(e.type==='assignment'?'<button class="btn secondary calendar-assignment" data-id="'+e.id+'" type="button">'+(e.status==='To submit'||e.status==='Overdue'?'Open assignment':'View submission')+'</button>':e.mode==='online'?'<a class="btn secondary" href="'+esc(e.location)+'" target="_blank" rel="noopener noreferrer">Open meeting link ↗</a>':'<p class="small">Venue: '+esc(e.location)+'</p>')+'</article>';}
function studentCalendar(year=new Date().getUTCFullYear(),month=new Date().getUTCMonth(),course='',day=''){
 const {offset,keys}=calendarMonth(year,month),prefix=keys[0].slice(0,7),events=calendarEvents(assignments,sessions).filter(e=>(!course||e.courseId===course)&&new Date(e.at).toISOString().startsWith(prefix)),today=new Date().toISOString().slice(0,10),shown=day?events.filter(e=>new Date(e.at).toISOString().startsWith(day)):events;
 root.innerHTML=formHeading('My learning calendar','Assignment deadlines and confirmed classes. All dates and times use Liberia time.')+'<form class="search-row" id="calendar-course-filter"><label class="sr-only" for="calendar-course">Filter by course</label><select id="calendar-course" name="courseId"><option value="">All approved courses</option>'+options(accessibleCourses())+'</select><button class="btn secondary" type="submit">Filter calendar</button></form><section class="panel calendar-panel"><div class="calendar-toolbar"><button class="btn secondary" id="calendar-prev" type="button" aria-label="Previous month">←</button><h2>'+new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'Africa/Monrovia'}).format(new Date(Date.UTC(year,month,1)))+'</h2><button class="btn secondary" id="calendar-next" type="button" aria-label="Next month">→</button></div><div class="calendar-grid">'+['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>'<span class="calendar-weekday">'+d+'</span>').join('')+Array(offset).fill('<span aria-hidden="true"></span>').join('')+keys.map((key,i)=>{const count=events.filter(e=>new Date(e.at).toISOString().startsWith(key)).length;return '<button class="calendar-day '+(day===key?'selected':'')+'" data-date="'+key+'" type="button" '+(key===today?'aria-current="date" ':'')+'aria-pressed="'+(day===key)+'" aria-label="'+key+', '+count+' events"><span>'+(i+1)+'</span>'+(count?'<small>'+count+'<span class="sr-only"> events</span></small>':'')+'</button>';}).join('')+'</div><p class="small muted" style="margin-top:16px">Select a date to view its deadlines and classes.</p><div class="btn-row"><button class="btn secondary" id="calendar-today" type="button">Today</button><button class="btn secondary" id="calendar-all" type="button">Show whole month</button></div></section><div class="section-heading"><h2>'+(day?'Events on '+esc(day):'This month’s agenda')+'</h2><span class="small muted">'+shown.length+' events</span></div>'+(shown.length?'<div class="course-grid">'+shown.map(calendarCard).join('')+'</div>':'<div class="empty">No deadlines or classes match this selection.</div>');backBinding();document.getElementById('calendar-course').value=course;
 const shift=n=>{const d=new Date(Date.UTC(year,month+n,1));studentCalendar(d.getUTCFullYear(),d.getUTCMonth(),course);};document.getElementById('calendar-prev').onclick=()=>shift(-1);document.getElementById('calendar-next').onclick=()=>shift(1);document.getElementById('calendar-today').onclick=()=>studentCalendar(undefined,undefined,course,today);document.getElementById('calendar-all').onclick=()=>studentCalendar(year,month,course);document.getElementById('calendar-course-filter').onsubmit=e=>{e.preventDefault();studentCalendar(year,month,new FormData(e.target).get('courseId'));};document.querySelectorAll('.calendar-day').forEach(b=>b.onclick=()=>studentCalendar(year,month,course,b.dataset.date));document.querySelectorAll('.calendar-assignment').forEach(b=>b.onclick=()=>submissionForm(assignments.find(a=>a.id===b.dataset.id)));
}
async function courseAnnouncements(course=''){
 root.innerHTML=formHeading('Course announcements','Updates from your course staff.')+loadingScreen('Loading announcements…','Retrieving your course updates.');backBinding();
 try{const staff=['admin','lecturer'].includes(profile.role),r=await api('/announcements'+(course?'?courseId='+encodeURIComponent(course):''));
 root.innerHTML=formHeading('Course announcements',staff?'Prepare announcements for your assigned courses. Drafts stay private until you publish.':'Published notices for your approved courses.')+'<form class="search-row" id="announcement-filter"><label class="sr-only" for="announcement-course">Course</label><select id="announcement-course" name="courseId"><option value="">'+(staff?'All assigned courses':'All approved courses')+'</option>'+options(accessibleCourses())+'</select><button class="btn secondary" type="submit">View announcements</button></form>'+(staff?'<button class="btn" id="new-announcement" type="button" style="margin-bottom:20px">Create announcement</button>':'')+r.announcements.map(a=>'<article class="panel"><span class="pill">'+(a.published?'Published':'Draft · staff only')+'</span><p class="small muted" style="margin-top:14px">'+esc(label(a.course_id))+' · '+time(a.updated_at)+'</p><h2>'+esc(a.title)+'</h2><p class="announcement-content">'+esc(a.content)+'</p>'+(staff?'<button class="btn secondary edit-announcement" data-id="'+a.id+'" type="button">Edit announcement</button>':'')+'</article>').join('')+(r.announcements.length?'':'<div class="empty">No announcements are available for these courses yet.</div>');backBinding();document.getElementById('announcement-course').value=course;document.getElementById('announcement-filter').onsubmit=e=>{e.preventDefault();courseAnnouncements(new FormData(e.target).get('courseId'));};if(staff){document.getElementById('new-announcement').onclick=()=>announcementEditor();document.querySelectorAll('.edit-announcement').forEach(b=>b.onclick=()=>announcementEditor(r.announcements.find(a=>a.id===b.dataset.id)));}
 }catch(error){loadingFailure(error);}
}
function announcementEditor(a){
 const scope=accessibleCourses();root.innerHTML=formHeading(a?'Edit announcement':'Create announcement','Publish a course notice for approved students, or save it as a staff draft.')+(!scope.length?'<div class="empty">Ask TIME to assign your teaching courses first.</div>':'<form class="panel" id="announcement-editor"><div class="field"><label for="notice-course">Course</label><select id="notice-course" name="courseId" '+(a?'disabled':'')+'>'+options(scope)+'</select></div><div class="field"><label for="notice-title">Announcement title</label><input id="notice-title" name="title" maxlength="160" required value="'+esc(a?.title||'')+'"></div><div class="field"><label for="notice-content">Announcement text</label><textarea id="notice-content" name="content" maxlength="8000" required>'+esc(a?.content||'')+'</textarea></div><label><input type="checkbox" name="published" '+(a?.published?'checked':'')+'> Publish for approved course students</label><p class="small muted">Announcements appear inside TIME Learning. They are not sent by email or push notification.</p><button class="btn" type="submit">Save announcement</button><div id="account-status" role="status" aria-live="polite"></div></form>');backBinding();if(!scope.length)return;if(a)document.getElementById('notice-course').value=a.course_id;
 document.getElementById('announcement-editor').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const fd=new FormData(e.target);await api(a?'/announcements/'+a.id:'/announcements',a?'PUT':'POST',{courseId:a?.course_id||fd.get('courseId'),title:fd.get('title'),content:fd.get('content'),published:fd.has('published')});announcements=(await api('/announcements')).announcements;await courseAnnouncements();feedback('Announcement saved.');}catch(error){feedback(error.message,true);}finally{button.disabled=false;}};
}

const attendanceLabel=status=>({present:'Present',late:'Late',absent:'Absent',excused:'Excused',unrecorded:'Not recorded'})[status]||status;
function attendanceClasses(course=''){
 const list=sessions.filter(s=>!course||s.course_id===course);
 root.innerHTML=formHeading('Class attendance','Attendance is recorded by course staff after a class starts. Unrecorded students are not marked absent automatically.')+'<form class="search-row" id="attendance-course-filter"><label class="sr-only" for="attendance-course">Course</label><select id="attendance-course" name="courseId"><option value="">All assigned courses</option>'+options(accessibleCourses())+'</select><button class="btn secondary" type="submit">Filter classes</button></form>'+list.map(s=>'<article class="panel"><span class="pill">'+esc(s.mode)+'</span><h2 style="margin-top:14px">'+esc(s.title)+'</h2><p class="small muted">'+esc(label(s.course_id))+'<br>'+time(s.starts_at)+'</p><button class="btn secondary open-attendance" data-id="'+s.id+'" type="button">'+(Date.parse(s.starts_at)>Date.now()?'View class roster':'Record / review attendance')+'</button></article>').join('')+(list.length?'':'<div class="empty">No scheduled classes are available for this selection. Schedule a class first.</div>');backBinding();document.getElementById('attendance-course').value=course;document.getElementById('attendance-course-filter').onsubmit=e=>{e.preventDefault();attendanceClasses(new FormData(e.target).get('courseId'));};document.querySelectorAll('.open-attendance').forEach(b=>b.onclick=()=>attendanceRoster(b.dataset.id));
}
async function attendanceRoster(id,offset=0){
 root.innerHTML=formHeading('Class attendance','Retrieving the approved student roster.')+loadingScreen('Loading attendance…','Retrieving current attendance records.');backBinding();
 try{const r=await api('/attendance/sessions/'+id+'?offset='+offset),future=Date.parse(r.session.starts_at)>Date.now();
 root.innerHTML=formHeading(r.session.title,label(r.session.course_id)+' · '+time(r.session.starts_at))+'<p class="notice">'+(future?'This class has not started. You can view the roster now and record attendance after the start time.':'Choose each student’s attendance status and save it. Notes are visible to the student. Use Not recorded to clear an incorrect mark without deleting its audit history.')+'</p><button class="btn secondary" id="attendance-classes" type="button" style="margin-bottom:20px">← All classes</button>'+r.students.map(u=>'<form class="panel attendance-form" data-student="'+u.student_id+'"><h2>'+esc(u.name)+'</h2><p class="small muted">'+esc(u.email)+' · '+esc(u.cohort)+'</p><div class="field"><label for="attendance-status-'+u.student_id+'">Attendance status</label><select id="attendance-status-'+u.student_id+'" name="status">'+['unrecorded','present','late','absent','excused'].map(s=>'<option value="'+s+'" '+(s===u.status?'selected':'')+'>'+attendanceLabel(s)+'</option>').join('')+'</select></div><div class="field"><label for="attendance-note-'+u.student_id+'">Note visible to student (optional)</label><textarea id="attendance-note-'+u.student_id+'" name="note" maxlength="1000" style="min-height:85px">'+esc(u.note)+'</textarea></div><button class="btn" type="submit" '+(future?'disabled':'')+'>Save attendance</button><p class="small muted" id="attendance-result-'+u.student_id+'" role="status" aria-live="polite" style="margin-top:12px">'+(u.updated_at?'Last saved '+time(u.updated_at):'Not recorded yet')+'</p></form>').join('')+(r.students.length?'':'<div class="empty">There are no active, approved students in this course.</div>')+paginationHTML(offset,r.total);backBinding();document.getElementById('attendance-classes').onclick=()=>attendanceClasses(r.session.course_id);adminPagination(offset,r.total,n=>attendanceRoster(id,n));
 document.querySelectorAll('.attendance-form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button'),result=document.getElementById('attendance-result-'+form.dataset.student);button.disabled=true;result.textContent='Saving attendance…';try{const fd=new FormData(form);await api('/attendance/sessions/'+id,'PUT',{studentId:form.dataset.student,status:fd.get('status'),note:fd.get('note')});result.textContent='Attendance saved successfully.';}catch(error){result.textContent=error.message;}finally{button.disabled=false;}});
 }catch(error){loadingFailure(error);}
}
async function myAttendance(){
 root.innerHTML=formHeading('My attendance','Your recorded online and in-person class attendance.')+loadingScreen('Loading attendance…','Retrieving your own class records.');backBinding();
 try{const r=await api('/attendance/my'),counts=status=>r.attendance.filter(a=>a.status===status).length;
 root.innerHTML=formHeading('My attendance','Only attendance recorded by course staff appears here. Ask your lecturer if a record needs correction.')+'<div class="stats student-stats">'+['present','late','absent','excused'].map(status=>'<div class="stat"><strong>'+counts(status)+'</strong><span>'+attendanceLabel(status)+'</span></div>').join('')+'</div><p class="small muted">'+r.attendance.length+' recorded class entries (up to the most recent 200). Unrecorded classes are not counted as absences.</p>'+r.attendance.map(a=>'<article class="panel"><span class="pill">'+attendanceLabel(a.status)+'</span><h2 style="margin-top:14px">'+esc(a.title)+'</h2><p class="small muted">'+esc(label(a.course_id))+' · '+esc(a.mode)+'<br>'+time(a.starts_at)+'</p>'+(a.note?'<p class="announcement-content">'+esc(a.note)+'</p>':'')+'<p class="small muted">Updated '+time(a.updated_at)+'</p></article>').join('')+(r.attendance.length?'':'<div class="empty">No attendance has been recorded for you yet.</div>');backBinding();
 }catch(error){loadingFailure(error);}
}

